/* Standalone design prototype. All installations, checks and operations are simulated. */
'use strict';
import { databaseBackupPlan } from './backup-policy.mjs';
import { createOnboardingUI } from './onboarding.mjs';
const icons={
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',
  server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M17 6.5h1M17 17.5h1"/>',
  import:'<path d="M12 3v12m-4-4 4 4 4-4M4 15v4a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-4"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  restore:'<path d="M3 10a9 9 0 1 1 2.5 8M3 4v6h6M12 7v5l3 2"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',
  folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
  database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',
  settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1M5.6 18.4l2.1-2.1m8.6-8.6 2.1-2.1"/><circle cx="12" cy="12" r="5"/>',
  update:'<path d="M20 7a8 8 0 0 0-13-2L3 9m0-6v6h6M4 17a8 8 0 0 0 13 2l4-4m0 6v-6h-6"/>',
  activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
  moon:'<path d="M20.8 13A9 9 0 0 1 11 3.2 9 9 0 1 0 20.8 13Z"/>',
  user:'<circle cx="12" cy="8" r="3"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4M12 17h.01"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  drive:'<path d="m5 4-3 12v4h20v-4L19 4H5ZM2 16h20M17 18h.01"/>',
  cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',
  warning:'<path d="m12 3 10 18H2L12 3ZM12 9v5m0 3h.01"/>',
  image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-5-5L5 21"/>',
  link:'<path d="m10 13 4-4m-6 7-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 10a4 4 0 0 0 6 0l4-4a4 4 0 0 0-6-6l-1 1"/>',
  play:'<path d="m8 4 12 8-12 8V4Z"/>',
  stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  document:'<path d="M14 2H5v20h14V7l-5-5ZM14 2v5h5M8 12h8m-8 4h8"/>',
  arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',
  loader:'<path d="M21 12a9 9 0 1 1-9-9"/>',
  network:'<rect x="9" y="2" width="6" height="6" rx="1"/><rect x="2" y="16" width="6" height="6" rx="1"/><rect x="16" y="16" width="6" height="6" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',
  key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-3-3 3-3m-6 0 3-3"/>'
};
const $=s=>document.querySelector(s);
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,style='',ico='',extra='')=>`<button class="button ${style}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const badge=(text,type='',ico='')=>`<span class="badge ${type}">${ico?icon(ico):''}${text}</span>`;
const state={view:'welcome',theme:'dark',menu:false,flow:'import',step:0,source:'family',scenario:'normal',installed:false,running:true,ml:false,release:'3.2.0',operation:null,backupCount:3,recoveryDownloaded:false,settingsAccepted:false,confirmCutover:false,sourceStopped:false,backupMode:'recent',backupCatalog:[],backupCheckedAt:Date.now(),fresh:{name:'Home library',path:'/srv/frameleaf/library',database:'/srv/frameleaf/database',backup:'/srv/backups/frameleaf',port:'2283'},activity:[]};
try{state.theme=localStorage.getItem('frameleaf-manager-theme')||'dark'}catch{}
document.documentElement.dataset.theme=state.theme;
const app=$('#app');
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3800)}
function modal(title,body,footer=''){const d=$('#dialog');d.innerHTML=`<button class="button quiet icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button><div class="modal-body"><h2 id="dialog-title">${title}</h2>${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal()}
function go(view){state.view=view;state.menu=false;render();$('.page-scroll')?.scrollTo({top:0,behavior:'instant'});$('#main h1')?.focus({preventScroll:true})}
function nav(label,ico,view,count=''){return `<button class="nav-item ${state.view===view||(view==='welcome'&&['import','fresh','restore','progress','success','profile','verify-account','downloads','phone','setup-complete'].includes(state.view))?'active':''}" data-action="nav:${view}" ${state.view===view?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${count?`<span class="nav-badge">${count}</span>`:''}</button>`}
function shell(main,right){const area={welcome:'Setup',import:'Immich import',fresh:'New installation',restore:'Restore backup',progress:'Operation in progress',success:'Server ready',profile:'Your details','verify-account':'Frameleaf account',downloads:'Get the app',phone:'Library preparation','setup-complete':'Setup complete',overview:'Overview',services:'Services',storage:'Storage',backups:'Backups',updates:'Updates',activity:'Activity',settings:'Manager settings'}[state.view]||'Setup';return `<div class="shell ${['profile','verify-account','downloads','phone','setup-complete'].includes(state.view)?'onboarding-layout':''} ${state.menu?'menu-open':''}"><header class="topbar"><button class="button quiet icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><button class="brand" data-action="nav:welcome" aria-label="Frameleaf Manager home"><img class="brand-dark" src="assets/frameleaf-logo-white.svg" alt="Frameleaf"><img class="brand-light" src="assets/frameleaf-logo-light.svg" alt="Frameleaf"><span class="brand-divider"></span><span class="brand-label">Manager</span></button><span class="prototype-pill">Prototype · Sample data</span><div class="topbar-right">${button('', 'theme','quiet icon-button',state.theme==='dark'?'sun':'moon','aria-label="Toggle light or dark theme" title="Toggle theme"')}<button class="row account-button" data-action="account"><span class="avatar">${icon('user')}</span><span class="local-account">Local admin</span></button></div></header><div class="workspace"><button class="mobile-shade" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar"><div class="server-select">${icon('server')}<div><strong>Home server</strong><small>Linux · Local Docker</small></div></div><nav aria-label="Manager"><p class="nav-caption">Installation</p>${nav('Set up Frameleaf','plus','welcome')}${nav('Overview','grid','overview')}${nav('Services','server','services')}${nav('Storage','drive','storage')}<p class="nav-caption separated">Protection & maintenance</p>${nav('Backups','shield','backups')}${nav('Updates','update','updates','1')}${nav('Activity','activity','activity')}<p class="nav-caption separated">Administration</p>${nav('Manager settings','settings','settings')}</nav><div class="sidebar-bottom">${button('Prototype guide','guide','quiet','help')}<div class="server-foot"><span class="status-dot"></span>Docker connected<p>Local management · HTTPS</p></div></div></aside><div class="page-area"><div class="contextbar"><span>Manager</span><span class="mobile-prototype">· Prototype</span>${icon('chevron')}<strong>${area}</strong><div class="context-actions"><span>Preview</span><select id="preview-state" aria-label="Choose prototype scenario"><option value="first" ${!state.installed?'selected':''}>First launch</option><option value="installed" ${state.installed?'selected':''}>Installed library</option><option value="mobile">Mobile onboarding</option><option value="multiple">Multiple Immich installs</option><option value="unsupported">Unsupported source</option></select></div></div><div class="page-scroll"><main id="main" class="page">${main}</main></div></div><aside class="inspector" aria-label="Context and installation details">${right||hostInspector()}</aside></div></div>`}
function heading(title,sub,action=''){return `<div class="page-heading"><div class="spread"><h1 tabindex="-1">${title}</h1>${action}</div>${sub?`<p>${sub}</p>`:''}</div>`}
function hostInspector(){return `<section class="inspector-section"><div class="spread"><h2>This server</h2>${icon('server')}</div><dl class="definition"><div><dt>Host</dt><dd>home-server</dd></div><div><dt>Platform</dt><dd>Linux amd64</dd></div><div><dt>Docker</dt><dd>Engine 28.4</dd></div><div><dt>Memory</dt><dd>16 GB</dd></div><div><dt>Processor</dt><dd>8 cores</dd></div></dl></section><section class="inspector-section"><h3>Storage available</h3><div class="meter"><span style="width:28%"></span></div><div class="spread meta"><span>1.12 TB used</span><span>4 TB total</span></div><p class="mt8">2.88 TB available for your library and services.</p></section><section class="inspector-section"><h3>Made for your server</h3><ul class="checklist"><li>${icon('check')}Your media stays on your server</li><li>${icon('check')}No Frameleaf Cloud account required</li><li>${icon('check')}You choose when to update</li></ul></section><div class="inspector-note">${icon('lock')}<p>Manager has its own local administrator account.</p></div><div class="inspector-footer">Sample server for this prototype.</div>`}
function welcome(){return heading('Choose how to begin','Set up and look after Frameleaf from one place.')+`<section class="card detected-card"><div class="card-body"><div class="detected-label">${icon('check')}FOUND ON THIS SERVER</div><div class="feature-row"><div class="icon-tile green-tile">${icon('import')}</div><div class="feature-copy"><h2>Bring your Immich library</h2><p>Import your accounts, albums, and settings. Keep your photos and external libraries exactly where they are.</p></div>${badge('Immich v3.1.0')}</div><div class="mini-stats"><div><strong>24,860</strong><small>Photos & videos</small></div><div><strong>4</strong><small>People</small></div><div><strong>126</strong><small>Albums</small></div><div><strong>2</strong><small>External libraries</small></div></div></div><div class="card-footer"><span class="safety-note">${icon('folder')}Existing media locations preserved</span>${button('Review import','start-import','primary')}</div></section><p class="section-label">Or start another way</p><div class="two-cols"><section class="card option-card"><div class="card-body"><div class="icon-tile">${icon('plus')}</div><h2>Set up a new library</h2><p>Choose your storage and let Manager prepare a fresh Frameleaf installation.</p><button class="text-button" data-action="start-fresh">Set up Frameleaf</button></div></section><section class="card option-card"><div class="card-body"><div class="icon-tile">${icon('restore')}</div><h2>Restore a backup</h2><p>Restore your database and reconnect media that already exists on your server.</p><button class="text-button" data-action="start-restore">Choose a backup</button></div></section></div><p class="quiet-note">${icon('info')}You can review every change before setup or import begins.</p>`}
function steps(items,current){return `<ol class="steps" aria-label="Setup progress">${items.map((s,i)=>`<li class="${i===current?'active':i<current?'complete':''}" ${i===current?'aria-current="step"':''}><span class="step-number">${i<current?icon('check'):i+1}</span><span>${s}</span></li>`).join('')}</ol>`}
function footer(back,next,label,disabled=false){return `<div class="wizard-footer">${button('Back',back,'quiet')}<div class="actions">${button(label,next,'primary','',disabled?'disabled':'')}</div></div>`}
const sources={family:{name:'Family library',project:'immich-home',container:'photos-server',db:'photos-db',assets:'24,860',users:'4',albums:'126',size:'842 GB',required:'2 GB',databaseSize:'1.8 GB',base:'/srv/immich',volume:'immich_thumbnails',external:2},test:{name:'Test library',project:'immich-test',container:'test-photos',db:'test-db',assets:'512',users:'1',albums:'8',size:'5.6 GB',required:'60 MB',databaseSize:'42 MB',base:'/srv/immich-test',volume:'test_thumbnails',external:2}};
const src=()=>sources[state.source]||sources.family;
function notice(title,text,type='good',ico='shield'){return `<div class="notice ${type}">${icon(ico)}<div><strong>${title}</strong>${text?`<p>${text}</p>`:''}</div></div>`}
function field(label,key,value,help='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${key}" data-field="${key}" type="${type}" value="${esc(value)}" ${extra}>${help?`<small>${help}</small>`:''}</label>`}
function section(title,content,extra=''){return `<section class="card"><div class="card-header"><h2>${title}</h2>${extra}</div>${content}</section>`}
function listRow(ico,title,sub,value=''){return `<div class="list-row">${icon(ico)}<div><strong>${title}</strong>${sub?`<p>${sub}</p>`:''}</div>${value}</div>`}
function toggle(label,key,checked){return `<label class="toggle"><input type="checkbox" data-toggle="${key}" ${checked?'checked':''}><span class="toggle-track"></span><span>${label}</span></label>`}

function setBackupPreview(mode){
  state.backupMode=mode;state.backupCheckedAt=Date.now();
  const age=(mode==='older'?26:8)*3600000;
  state.backupCatalog=mode==='missing'?[]:Object.values(sources).map(source=>({sourceId:source.project,database:'immich',createdAt:new Date(state.backupCheckedAt-age).toISOString(),status:'completed',readable:mode!=='unusable',integrity:mode==='unusable'?'failed':'passed',size:source.databaseSize,path:source.base+'/library/backups/immich-database-backup.sql.gz'}));
}
function importBackupPlan(now=state.backupCheckedAt){return databaseBackupPlan(state.backupCatalog,{sourceId:src().project,database:'immich',now})}
function importStepIds(){return importBackupPlan().skipBackup?[0,1,3]:[0,1,2,3]}
function importSteps(current){const ids=importStepIds(),labels=['Installation','Library & settings','Database backup','Import'];return steps(ids.map(i=>labels[i]),ids.indexOf(current))}
function backupDiscoveryCard(){
  const plan=importBackupPlan(),item=state.backupCatalog.find(b=>b.sourceId===src().project);
  const label=plan.skipBackup?'Recent database backup found':state.backupMode==='missing'?'No database backup found':state.backupMode==='older'?'Latest database backup is older than 24 hours':'Existing database backup could not be verified';
  const detail=plan.skipBackup?'8 hours old · Same Immich installation · Readable dump verified':state.backupMode==='older'?'26 hours old · A new database backup is needed':state.backupMode==='unusable'?'The existing dump is unreadable or incomplete':'Manager checked the selected installation’s resolved backups folder';
  return `<div class="mt16">${section('Immich database backup',listRow(plan.skipBackup?'check':'database',label,detail,badge(plan.skipBackup?'Backup skipped':'Backup needed',plan.skipBackup?'good':'warning'))+`<div class="card-body" style="padding-top:0"><p class="meta mono">${esc(item?.path||src().base+'/library/backups')}</p><p class="meta mt8">${plan.skipBackup?'No backup page, destination selection, or new backup is needed.':'Only the database will be backed up. Photos, videos and external libraries are excluded.'}</p></div><div class="card-footer"><label for="backup-preview" class="sample-note">Backup preview</label><select id="backup-preview" style="width:auto;max-width:230px" aria-label="Choose Immich backup scenario"><option value="recent" ${state.backupMode==='recent'?'selected':''}>Recent · 8 hours old</option><option value="older" ${state.backupMode==='older'?'selected':''}>Older · 26 hours old</option><option value="missing" ${state.backupMode==='missing'?'selected':''}>No backup found</option><option value="unusable" ${state.backupMode==='unusable'?'selected':''}>Unreadable backup</option></select></div>`)}</div>`;
}

function importInspector(){const s=src();return `<section class="inspector-section"><h2>Import summary</h2><dl class="definition"><div><dt>Source</dt><dd>${s.name}</dd></div><div><dt>Version</dt><dd>${state.scenario==='unsupported'?'v2.5.0':'v3.1.0'}</dd></div><div><dt>Photos & videos</dt><dd>${s.assets}</dd></div><div><dt>Users</dt><dd>${s.users}</dd></div><div><dt>Albums</dt><dd>${s.albums}</dd></div><div><dt>Media</dt><dd>${s.size}</dd></div></dl></section><section class="inspector-section"><h3>What moves</h3><ul class="checklist"><li>${icon('check')}Accounts and permissions</li><li>${icon('check')}Albums and metadata</li><li>${icon('check')}Compatible settings</li></ul></section><section class="inspector-section"><h3>What stays in place</h3><p class="mt8">Your originals, derivatives, and external libraries keep the same locations and access modes.</p><p class="mt8">Your Immich database is retained separately.</p></section><section class="inspector-section"><h3>Planned downtime</h3><p class="mt8">Database import and verification determine downtime. No media is copied or backed up. Immich stays stopped after the switch.</p></section><div class="inspector-footer">Demonstration data · No source has been contacted.</div>`}
function discovery(){const s=src(),multiple=state.scenario==='multiple',blocked=state.scenario==='unsupported';return importSteps(0)+heading(multiple?'Choose an Immich installation':'We found your Immich installation','Review the source. Your existing database will be kept for recovery.')+(multiple?`<div class="stack mb16">${Object.entries(sources).map(([key,x])=>`<label class="radio-card"><input type="radio" name="source" value="${key}" ${state.source===key?'checked':''}><div><div class="spread"><strong>${x.name}</strong>${badge('Immich v3.1.0')}</div><p>${x.project} · ${x.assets} assets · ${x.size}</p></div></label>`).join('')}</div>`:'')+section(s.name,listRow('server',blocked?'Immich v2.5.0':'Immich v3.1.0',`Compose project · ${s.project}`,badge('Source'))+listRow('database','PostgreSQL 14','Database: immich · vector + VectorChord',badge('Configured','good'))+listRow('network','Database connection resolved',`${s.container} → ${s.db} · shared Docker network`,badge('Connected','good'))+listRow('folder','Media & external libraries',`4 mappings · ${s.size} of existing media`,badge('Preserved','good'))+`<details class="disclosure"><summary>Connection & configuration details</summary><p>Database credentials: configured through Docker secret reference.<br>Configuration file: /config/immich.json · loaded.<br>Source database: ${s.db}:5432/immich.<br>Server image, Compose labels and the configured database connection agree.</p></details>`)+`<div class="mt16">${blocked?notice('This source version is not supported','Choose a version qualified for import before continuing. Your source installation is unchanged.','warning','warning'):notice('A separate database for Frameleaf','Manager imports a logical copy into a new PostgreSQL volume. Your original Immich database stays in place.')}</div>`+(state.source?backupDiscoveryCard():'')+footer('nav:welcome','import-next','Review library & settings',blocked||(multiple&&!state.source))}
function mappings(){const s=src();const rows=[['Media library',s.base+'/library','Bind mount','/data','Read & write'],['Thumbnails',s.volume,'Named volume','/data/thumbs','Read & write'],['Family archive','/srv/family-archive','Bind mount','/external/archive','Read only'],['Scanned photographs','/srv/scans','Bind mount','/photos/scans','Read only']];return `<div class="table-wrap"><table><thead><tr><th>Source location</th><th>Inside container</th><th>Access</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="mapping-source"><strong>${r[0]}</strong><small><code>${r[1]}</code></small><small>${r[2]}</small></td><td class="mapping-destination"><code>${r[3]}</code></td><td>${badge(r[4])}</td></tr>`).join('')}</tbody></table></div>`}
function mappingReview(){return importSteps(1)+heading('Your library, in the same place','These exact mappings will be used by Frameleaf so existing photo paths keep working.')+section('Preserved media mappings',mappings(),badge('4 of 4 preserved','good'))+`<div class="mt16">${section('Settings compatibility',`<div class="settings-row"><span>Users, albums & permissions</span><span>Imported from database</span>${badge('Preserved','good')}</div><div class="settings-row"><span>Storage template & time zone</span><span>From configuration file</span>${badge('Preserved','good')}</div><div class="settings-row"><span>Email notifications</span><span>SMTP credentials configured</span>${badge('Preserved','good')}</div><div class="settings-row"><span>Database connection</span><span>New credentials generated</span>${badge('Recreated')}</div><div class="settings-row"><span>OAuth callback URL</span><span>Points to the Immich address</span>${badge('Review needed','warning')}</div>`)}</div><div class="notice warning mt16">${icon('warning')}<div><strong>Update your OAuth callback after import</strong><p>Local account sign-in remains available. External sign-in stays off until the provider callback uses your Frameleaf address.</p></div></div><label class="check-row mt24"><input type="checkbox" data-check="settingsAccepted" ${state.settingsAccepted?'checked':''}><span>I’ve reviewed the mappings and the setting that needs attention.</span></label>${footer('import-back','import-next',importBackupPlan().skipBackup?'Review cutover':'Review database backup',!state.settingsAccepted)}`}
function recoveryReview(){const reason=state.backupMode==='older'?'The latest dump is 26 hours old. A backup must be 24 hours old or less to skip this step.':state.backupMode==='unusable'?'The existing dump could not be verified. Manager will create a usable database backup.':'No usable database backup was found for this Immich installation.';return importSteps(2)+heading('Back up the Immich database',reason)+section('Database backup only',`<div class="card-body"><label class="field"><span>Backup destination</span><input value="${esc(src().base+'/library/backups')}" readonly><small>Resolved from this Immich installation’s existing backup location.</small></label><div class="breakdown mt16"><div><strong>${src().databaseSize}</strong><small>Estimated database dump</small></div><div><strong>${src().required}</strong><small>Space needed</small></div><div><strong>2.88 TB</strong><small>Available</small></div></div></div><div class="card-footer"><span class="safety-note">${icon('database')}Immich database · .sql.gz</span>${badge('Media excluded')}</div>`)+`<div class="notice good mt16">${icon('check')}<div><strong>Your photos stay in place</strong><p>No photos, videos, thumbnails, or external-library files will be backed up. Manager will stop Immich and verify the database dump before starting Frameleaf.</p></div></div>`+footer('import-back','import-next','Review cutover')}
function cutoverReview(){const plan=importBackupPlan();const tasks=[['Recheck this installation','Confirm the reviewed database, mappings and settings. Recheck the selected backup’s age and usability at cutover.'],['Stop Immich and secure the library','Stop the application and workers; disable their automatic restart.'],...(!plan.skipBackup?[['Create and verify a database backup',`Back up only the ${src().databaseSize} Immich database. Media is excluded.`]]:[]),['Import the current database into Frameleaf','Copy the stopped source database into a new PostgreSQL volume. The recovery backup is not used as the import data.'],['Start Frameleaf and verify your library','Check sign-in, users, albums, assets, existing media access and background work.']];return importSteps(3)+heading('Ready to switch to Frameleaf','Your library will be unavailable while Manager imports the current Immich database.')+(plan.skipBackup?`<div class="mb16">${notice('Existing Immich backup reused · Backup step skipped','A verified database backup from 8 hours ago is available. Manager will not create another backup.','good','check')}</div>`:'')+section('The cutover plan',`<div class="card-body"><ol class="timeline">${tasks.map((item,i)=>`<li><span class="stage-icon">${i+1}</span><div><strong>${item[0]}</strong><p>${item[1]}</p></div></li>`).join('')}</ol></div>`)+`<div class="notice warning mt16">${icon('lock')}<div><strong>Only Frameleaf will write to these media locations</strong><p>Immich stays stopped after import. Database backups do not restore media or undo changes to files. Returning to Immich after Frameleaf writes requires a separate recovery review.</p></div></div><label class="check-row mt24"><input type="checkbox" data-check="confirmCutover" ${state.confirmCutover?'checked':''}><span>I understand Immich will stay stopped and this backup covers only the database.</span></label>${footer('import-back','begin-import','Start import preview',!state.confirmCutover)}<p class="sample-note mt16">Simulated backup discovery and import. No real database or files are accessed.</p>`}
function importFlow(){return [discovery,mappingReview,recoveryReview,cutoverReview][state.step]()}
function freshFlow(){const titles=['Administrator','Storage','Checks','Install'];let body='';if(state.step===0){body=heading('Secure your Manager','Create the local administrator account used to manage this server.')+section('Local administrator',`<div class="card-body"><form id="admin-form" class="form-grid">${field('Administrator name','admin','owner','Used only to sign in to Manager.','text','autocomplete="off" required')}${field('Password','password','sample-only-password','Use a sample password in this prototype.','password','autocomplete="new-password" minlength="12" required')}<div class="notice good field full">${icon('lock')}<div><strong>Local HTTPS and a separate account</strong><p>Manager credentials are independent of your Frameleaf photo account. No Cloud account is required.</p></div></div></form></div>`)+footer('nav:welcome','fresh-next','Continue to storage')}else if(state.step===1){body=heading('Give your library a home','Choose the server locations and connection settings for this installation.')+section('Storage & access',`<div class="card-body"><form id="storage-form" class="form-grid">${field('Library name','name',state.fresh.name)}${field('Frameleaf port','port',state.fresh.port,'Manager remains on its own HTTPS port.','number','min="1024" max="65535" required')}${field('Media location','path',state.fresh.path,'Originals and generated media.','text','required')}${field('Database location','database',state.fresh.database,'A new, dedicated PostgreSQL volume.','text','required')}${field('Database backup destination','backup',state.fresh.backup,'Database dumps only. Media is excluded.','text','required')}</form></div>`)+`<div class="mt16">${section('Processing',`<div class="list-row">${icon('cpu')}<div><strong>CPU processing</strong><p>Works with this server’s 8-core processor.</p></div>${badge('Default')}</div><div class="list-row">${icon('image')}<div><strong>Machine learning</strong><p>Enable face recognition and smart search.</p></div>${toggle('Enable','ml',state.ml)}</div>`)}</div>`+footer('fresh-back','fresh-next','Check this configuration')}else if(state.step===2){const check=state.validation||'ok';const errors={port:['Frameleaf port','Port 2283 is already in use. Choose another port.'],path:['Storage permissions','Manager cannot write to the selected media location.'],space:['Free space','This destination needs at least 20 GB free.'],registry:['Image registry','The registry is unavailable. Your installation has not changed.'],signature:['Release signature','The release bundle could not be verified. Choose a verified release.'],architecture:['Image architecture','This image set does not support the selected host architecture.']};body=heading(check==='ok'?'This server is ready':'Resolve this before installing','Manager checks storage, compatibility, and the complete release bundle.')+`<div class="spread mb16"><span class="sample-note">Validation preview</span><select id="validation-scenario" aria-label="Choose validation result" style="width:auto"><option value="ok" ${check==='ok'?'selected':''}>All checks pass</option>${Object.entries(errors).map(([k,v])=>`<option value="${k}" ${check===k?'selected':''}>${v[0]} problem</option>`).join('')}</select></div>`+section('Preflight checks',[['path','Storage permissions','Media, database and backup destinations writable'],['space','Free space','2.88 TB available · 20 GB needed for services'],['port','Frameleaf port',`Port ${esc(state.fresh.port)} available`],['docker','Docker compatibility','Engine and Compose versions supported'],['architecture','Image architecture','Linux amd64 images available'],['registry','Image registry','All required image digests available'],['signature','Release signature','Manifest and image set verified']].map(([k,t,desc])=>listRow(check===k?'warning':'check',t,check===k?errors[check][1]:desc,badge(check===k?'Action needed':'Passed',check===k?'warning':'good'))).join(''))+(check!=='ok'?`<div class="mt16">${notice('Installation is paused',errors[check][1],'warning','warning')}</div>`:'')+footer('fresh-back','fresh-next','Review installation',check!=='ok')}else{body=heading('Ready to set up Frameleaf','Manager will prepare the services and take you into Frameleaf when your library is ready.')+section('New installation',listRow('image',esc(state.fresh.name),'Frameleaf 3.2.0 · Verified release bundle')+listRow('folder','Photo library',`<code>${esc(state.fresh.path)}</code>`)+listRow('database','New PostgreSQL database',`<code>${esc(state.fresh.database)}</code> · Credentials generated`)+listRow('shield','Encrypted database backups',`<code>${esc(state.fresh.backup)}</code>`)+listRow('network','Local address',`https://home-server:${esc(state.fresh.port)}`)+listRow('cpu','Processing',state.ml?'CPU with machine learning':'CPU · Machine learning off'))+`<div class="mt16">${notice('Managed independently','Your photo library keeps running even when Manager is unavailable. You can export its configuration for manual recovery.')}</div>`+footer('fresh-back','begin-install','Install preview')+`<p class="sample-note mt16">This installs sample services in the prototype only.</p>`}return steps(titles,state.step)+body}
function restoreFlow(){if(state.step===0)return steps(['Database backup','Recovery point','Restore'],0)+heading('Restore your database','Connect a database backup and keep your existing media locations available.')+section('Database backup repository',`<div class="card-body"><div class="form-grid"><label class="field full"><span>Mounted backup destination</span><select><option>/srv/backups/frameleaf · Backup drive</option><option>/mnt/backup-drive/frameleaf · External drive</option></select></label><label class="field full"><span>Recovery key</span><input id="restore-key" type="password" value="sample-recovery-key" autocomplete="off"><small>Sample key for an encrypted Manager database backup. Do not enter a real key.</small></label></div></div>`)+`<div class="mt16">${notice('Your media must already be available','Manager restores the database into a new, empty PostgreSQL volume. Photos, videos and external-library files are not included.','','database')}</div>`+footer(state.installed?'nav:backups':'nav:welcome','restore-next','Unlock backup preview');if(state.step===1)return steps(['Database backup','Recovery point','Restore'],1)+heading('Choose a database recovery point','Database records and metadata will return to the selected time. Media files are not restored.')+`<div class="stack">${[['latest','Today, 02:00','Scheduled database backup · Frameleaf 3.2.0'],['before-update','Yesterday, 15:42','Before update · Frameleaf 3.2.0']].map(([id,t,d],i)=>`<label class="radio-card"><input type="radio" name="snapshot" value="${id}" ${(state.snapshot||'latest')===id?'checked':''}><div><div class="spread"><strong>${t}</strong>${badge(i===0?'Latest':'Verified',i===0?'good':'')}</div><p>${d}</p><p>1.8 GB · Database only</p></div></label>`).join('')}</div>`+footer('restore-back','restore-next','Review restore');return steps(['Database backup','Recovery point','Restore'],2)+heading('Review your database restore','Restore the database and reconnect your existing library files.')+section('Recovery destination',listRow('clock','Database snapshot',state.snapshot==='before-update'?'Yesterday, 15:42 · Before update':'Today, 02:00 · Scheduled backup')+listRow('database','Database','New, empty Frameleaf PostgreSQL volume')+listRow('folder','Existing media',`<code>${esc(src().base+'/library')}</code> · Reused in place`)+listRow('folder','External libraries','/external/archive and /photos/scans · Existing mappings preserved')+listRow('shield','Verification','Database integrity, authenticated access and existing file references'))+`<div class="notice warning mt16">${icon('warning')}<div><strong>This restore does not recover media files</strong><p>Required files must already exist at the mapped locations. Manager checks those locations before starting the application.</p></div></div>`+footer('restore-back','begin-restore','Restore database preview')}
const stages={
  import:[['Revalidate the selected source','Database connection, mounts, settings, source version and backup status checked'],['Stop Immich and disable automatic restart','Application and workers stopped; exclusive writable media ownership confirmed'],['Copy the current database','Logical dump of the stopped source restored into a new Frameleaf PostgreSQL volume'],['Adopt and migrate','Frameleaf’s official-origin adoption completed'],['Verify the imported library','Sign-in, counts, representative checksums, existing external libraries and jobs checked']],
  install:[['Verify the release bundle','Signature, eligibility and architecture checked'],['Download the complete image set','All required images pinned to verified digests'],['Prepare your storage','Permissions and service directories checked'],['Create the managed services','Unique project, network and new database credentials'],['Check application readiness','Authenticated setup and background processing available']],
  restore:[['Verify the database backup','Recovery key and database dump integrity checked'],['Check the existing media mappings','Required original files must already be accessible; no media will be restored'],['Restore the database','Restore into a new, empty PostgreSQL volume'],['Start the matching release','Compatible services connected to the existing media locations'],['Verify database and file references','Account access, database counts and representative existing files checked']],
  backup:[['Pause application writes','Finish current database work'],['Back up the database','Create an encrypted logical database dump only'],['Verify the database backup','Dump integrity checked and application resumed']],
  update:[['Verify release eligibility','Signed manifest, rollout and withdrawal status checked'],['Download compatible images','Complete image set downloaded before changing services'],['Create a database recovery point','Database dump verified; no media included'],['Apply the update','Schema migration and application startup completed'],['Verify your library','Authenticated access, background work and existing media access checked']]
};
function operationStages(kind){const list=stages[kind];if(kind!=='import'||state.operation?.skipDatabaseBackup)return list;return [...list.slice(0,2),['Create and verify the Immich database backup','Database only · No photos, videos, thumbnails or external libraries included'],...list.slice(2)]}

function operationTitle(kind){return {import:'Bringing your library to Frameleaf',install:'Setting up your Frameleaf',restore:'Restoring your library',backup:'Protecting your library',update:'Updating Frameleaf'}[kind]}
function progressView(){const o=state.operation,list=operationStages(o.kind),pct=Math.round(o.index/list.length*100);return heading(o.paused?'Operation paused':operationTitle(o.kind),o.paused?'Your last completed step has been saved. Resume from the next safe step.':'Manager keeps the operation running when you close this window.')+`<section class="card"><div class="card-body"><div class="spread progress-label"><span>${o.paused?'Paused':list[Math.min(o.index,list.length-1)][0]}</span><span>${pct}%</span></div><div class="progress" role="progressbar" aria-label="Operation progress" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div><ol class="timeline mt16">${list.map((s,i)=>`<li class="${i<o.index?'done':i===o.index?'running':''}"><span class="stage-icon">${i<o.index?icon('check'):i===o.index&&!o.paused?icon('loader','spin'):i+1}</span><div><strong>${s[0]}</strong><p>${s[1]}</p></div><span class="stage-time">${i<o.index?'Complete':i===o.index?o.paused?'Paused':'In progress':'Waiting'}</span></li>`).join('')}</ol></div><div class="card-footer"><span class="safety-note">${icon('shield')}Completed steps are recorded</span>${badge('Simulated operation')}</div></section><div class="wizard-footer"><span class="sample-note">Preview time is accelerated.</span><div class="actions">${button(o.paused?'Resume operation':'Simulate interruption',o.paused?'resume-operation':'pause-operation','quiet')}${button('Skip to result','finish-operation','primary')}</div></div>${o.kind==='import'?`<div class="mt16">${notice('Source protection',state.sourceStopped?'Immich is stopped. Automatic restart is disabled.':'Immich will be stopped before the current database is copied into Frameleaf.','good','lock')}</div>`:''}`}
let operationTimer;
function startOperation(kind){if(state.operation&&!state.operation.done){go('progress');return}state.operation={kind,index:0,paused:false,done:false,skipDatabaseBackup:kind==='import'&&importBackupPlan(Date.now()).skipBackup};go('progress');scheduleStage()}
function scheduleStage(){clearTimeout(operationTimer);const o=state.operation;if(!o||o.paused||o.done)return;operationTimer=setTimeout(()=>{if(o!==state.operation||o.paused)return;o.index++;if(o.kind==='import'&&o.index>=2)state.sourceStopped=true;if(o.index>=operationStages(o.kind).length)completeOperation();else{if(state.view==='progress')render();scheduleStage()}},1900)}
function completeOperation(){clearTimeout(operationTimer);const o=state.operation;if(!o)return;o.done=true;o.index=operationStages(o.kind).length;if(['import','install','restore'].includes(o.kind)){state.installed=true;state.running=true;state.installOrigin=o.kind;onboarding.start(o.kind)}if(o.kind==='backup')state.backupCount++;if(o.kind==='update')state.release='3.2.1';state.activity.unshift({title:{import:'Immich import verified',install:'Frameleaf installation complete',restore:'Backup restore verified',backup:'Encrypted backup verified',update:'Frameleaf update complete'}[o.kind],detail:'Sample operation · Completed just now'});go('success')}
function successView(){if(state.setup&&['import','install','restore'].includes(state.installOrigin)&&!['backup','update'].includes(state.operation?.kind))return onboarding.completionView();const kind=state.operation?.kind||'import',isImport=kind==='import',titles={import:'Your library is ready',install:'Welcome to Frameleaf',restore:'Your library is restored',backup:'Your backup is verified',update:'Frameleaf is up to date'};return `<div class="success-head"><div class="success-icon">${icon('check')}</div><h1 tabindex="-1">${titles[kind]}</h1><p>${{import:'The import checks passed. Your media is in its original location, ready for Frameleaf.',install:'Your services are ready. Continue in Frameleaf to create your photo account.',restore:'Your database has been restored and connected to the existing media locations.',backup:'Your encrypted database dump is verified. Media is not included.',update:'Your library is running on Frameleaf 3.2.1. Your previous database recovery point is available.'}[kind]}</p></div>`+(isImport||kind==='restore'?section('Library verification',`<div class="breakdown"><div><strong>${src().assets}</strong><small>Assets matched</small></div><div><strong>${src().users}</strong><small>Users matched</small></div><div><strong>${src().albums}</strong><small>Albums matched</small></div></div>`+['Authenticated access confirmed','Original and derivative sample checksums matched','Both external libraries accessible','Background processing verified'].map(x=>listRow('check',x,'',badge('Passed','good'))).join('')):section('Verified',listRow('check','Application consistency checked','Database integrity and service readiness checked',badge('Passed','good'))))+(isImport?`<div class="notice good mt16">${icon('lock')}<div><strong>Immich remains stopped</strong><p>Frameleaf owns the writable media locations. Your original database is retained. ${state.operation.skipDatabaseBackup?'The existing database backup was reused; no new backup was created.':'A database-only backup was created and verified.'}</p></div></div>`:'')+`<div class="wizard-footer"><span class="sample-note">Prototype result · No real data was changed</span><div class="actions">${button('View overview','nav:overview','quiet')}${kind==='backup'?button('View backups','nav:backups','primary'):button('Open Frameleaf','open-frameleaf','primary')}</div></div>`}
function noInstallation(title){return heading(title,'Your installation will appear here when setup is complete.')+`<div class="card empty"><div class="icon-tile">${icon('server')}</div><h2>No managed library yet</h2><p>Start a new library, import Immich, or restore a backup. You can also explore the dashboard with an installed example.</p><div class="row wrap" style="justify-content:center">${button('Start setup','nav:welcome','primary')}${button('Preview installed library','load-installed','quiet')}</div></div>`}
function overview(){if(!state.installed)return noInstallation('Overview');return onboarding.summaryBanner()+heading('Home library','Your photos, services, and recovery points at a glance.',button('Open Frameleaf','open-frameleaf','primary'))+`<div class="notice ${state.running?'good':'warning'} mb16">${icon(state.running?'check':'stop')}<div class="grow"><strong>${state.running?(state.setup&&!state.setup.managerFinished?'Your server is running':'Your library is ready'):'Your library is stopped'}</strong><p>${state.running?'All core services are ready · Last checked just now':'Start your services to make Frameleaf available.'}</p></div>${badge(state.running?'Ready':'Stopped',state.running?'good':'warning')}</div><div class="metric-grid"><section class="card metric"><span class="label">${icon('image')}Photos & videos</span><strong>${state.installOrigin==='install'?'0':src().assets}</strong><small>${state.installOrigin==='install'?'Ready for your first upload':'Across 126 albums'}</small></section><section class="card metric"><span class="label">${icon('drive')}Library storage</span><strong>${state.installOrigin==='install'?'0 GB':src().size}</strong><small>2.88 TB free on this server</small></section><section class="card metric"><span class="label">${icon('shield')}Latest backup</span><strong>02:00</strong><small>Today · Verified</small></section></div><div class="mt24">${section('Services',listRow('server','Frameleaf server','Photo library and API',badge(state.running?'Ready':'Stopped',state.running?'good':''))+listRow('database','PostgreSQL','Dedicated Frameleaf database',badge(state.running?'Ready':'Stopped',state.running?'good':''))+listRow('cpu','Machine learning',state.ml?'CPU · Face recognition & smart search':'Optional · CPU processing available',badge(state.ml&&state.running?'Ready':'Off',state.ml&&state.running?'good':'')),button('Manage','nav:services','quiet'))}</div><div class="two-cols mt16"><section class="card"><div class="card-body"><div class="row mb16">${icon('shield')}<h2>Database recovery points</h2></div><p class="muted" style="font-size:14px">Encrypted database dumps to your mounted backup drive. Media is excluded.</p><div class="spread mt16"><span class="meta">${state.backupCount} snapshots</span><button class="text-button" data-action="nav:backups">View backups</button></div></div></section><section class="card"><div class="card-body"><div class="row mb16">${icon('update')}<h2>${state.release==='3.2.1'?'Up to date':'An update is available'}</h2></div><p class="muted" style="font-size:14px">${state.release==='3.2.1'?'You are running Frameleaf 3.2.1.':'Frameleaf 3.2.1 is ready for your server. You choose when to install.'}</p><div class="spread mt16"><span class="meta">Stable channel</span><button class="text-button" data-action="nav:updates">${state.release==='3.2.1'?'View release':'Review update'}</button></div></div></section></div>`}
function servicePage(){if(!state.installed)return noInstallation('Services');return heading('Services','Manager owns this stack. Your library runs independently of the Manager container.',`${button(state.running?'Stop stack':'Start stack',state.running?'stop-stack':'start-stack',state.running?'quiet':'primary',state.running?'stop':'play')}`)+section('Frameleaf · home-library',[['server','Frameleaf server','frameleaf-server · '+state.release],['database','PostgreSQL','database · Dedicated Frameleaf volume'],['activity','Redis','redis · Job queue'],['cpu','Machine learning','immich-machine-learning · CPU']].map(([i,t,sub])=>listRow(i,t,sub,badge(i==='cpu'&&!state.ml?'Off':state.running?'Ready':'Stopped',state.running&&(i!=='cpu'||state.ml)?'good':''))).join(''),button('Restart stack','restart-stack','quiet','update'))+`<div class="mt16">${section('Recent server logs',`<pre class="log"><span class="log-time">10:24:16</span> <span class="log-ok">INFO</span> Application ready on port 2283
<span class="log-time">10:24:16</span> <span class="log-ok">INFO</span> Database connection established
<span class="log-time">10:24:17</span> <span class="log-ok">INFO</span> Background workers ready
<span class="log-time">10:24:17</span> <span class="log-ok">INFO</span> External libraries accessible: 2
<span class="log-time">10:24:18</span> <span class="log-ok">INFO</span> Settings loaded · credentials=[REDACTED]</pre>`,button('Download sample logs','export-logs','quiet','document'))}</div><p class="quiet-note">${icon('lock')}Logs are sanitized. Database passwords, tokens, and session credentials are never displayed.</p>`}
function storagePage(){if(!state.installed)return noInstallation('Storage');return heading('Storage','The paths your library uses, and the space available on this server.')+section('Library drive',`<div class="card-body"><div class="spread"><strong>1.12 TB used of 4 TB</strong><span class="muted">2.88 TB free</span></div><div class="meter" style="height:8px"><span style="width:21%"></span><span class="teal" style="width:7%"></span></div><div class="legend"><span><i></i>Media · 842 GB</span><span><i class="teal"></i>Other · 278 GB</span><span><i class="gray"></i>Available · 2.88 TB</span></div></div>`)+`<div class="mt16">${section('Media mappings',mappings(),badge('Preserved from Immich'))}</div><div class="notice good mt16">${icon('database')}<div><strong>Separate Frameleaf database</strong><p>Frameleaf uses its own PostgreSQL volume. The original Immich database is retained and is never opened by a different PostgreSQL version.</p></div></div>`}
function backupPage(){if(!state.installed)return noInstallation('Database backups');return heading('Database backups','Back up the database only. Photos, videos and external libraries stay in their existing locations.',button('Back up database','begin-backup','primary','database'))+section('Backup drive',listRow('drive','/srv/backups/frameleaf','Encrypted database dumps · 2.1 TB available',badge('Connected','good'))+listRow('clock','On demand','You control when Manager creates a database backup.')+listRow('key','Recovery key','For encrypted Manager database backups.',button('Export sample key','download-key','quiet')))+`<div class="mt24">${section('Database recovery points',`<div class="table-wrap"><table><thead><tr><th>Database backup</th><th>Size</th><th>Status</th><th></th></tr></thead><tbody><tr><td><strong>Today, 02:00</strong><small>Frameleaf database</small></td><td>1.8 GB<small>Database only</small></td><td>${badge('Verified','good')}</td><td>${button('Restore','start-restore','quiet')}</td></tr><tr><td><strong>Yesterday, 15:42</strong><small>Before update</small></td><td>1.8 GB<small>Database only</small></td><td>${badge('Verified','good')}</td><td>${button('Restore','restore-previous','quiet')}</td></tr><tr><td><strong>Existing Immich backup</strong><small>Reused for import · 8 hours old at review</small></td><td>1.8 GB<small>Database only</small></td><td>${badge('Retained')}</td><td>${button('Recovery notes','rollback','quiet')}</td></tr></tbody></table></div>`)}</div><div class="notice mt16">${icon('info')}<div><strong>Media is not part of these backups</strong><p>Restoring a database reconnects file references to media that already exists. It does not restore missing files.</p></div></div>`}
function updatesPage(){if(!state.installed)return noInstallation('Updates');return heading('Updates','Choose when to update. Manager prepares your database recovery point first.')+section(state.release==='3.2.1'?'Your installation is up to date':'Frameleaf 3.2.1 is available',`<div class="card-body"><div class="row gap8">${badge('Stable')}${badge('Signed release','good','shield')}<span class="meta">Current version ${state.release}</span></div><h3 class="mt24">Library reliability and performance</h3><ul class="checklist"><li>${icon('check')}Improved background processing reliability</li><li>${icon('check')}Faster library browsing and album loading</li><li>${icon('check')}Latest compatibility and security fixes</li></ul><p class="sample-note mt16">Illustrative release notes for this prototype.</p></div><div class="card-footer"><span class="safety-note">${icon('clock')}About 5–10 minutes of downtime</span>${button(state.release==='3.2.1'?'Check for updates':'Review update',state.release==='3.2.1'?'check-updates':'review-update',state.release==='3.2.1'?'quiet':'primary')}</div>`)+`<div class="mt16">${section('Release checks',listRow('shield','Signature & eligibility','Verified manifest, staged rollout and withdrawal status',badge('Passed','good'))+listRow('server','Complete compatible image set','Server, database, Redis and optional machine learning',badge('Available','good'))+listRow('restore','Database recovery point','Created before any service or schema changes',badge('Required')))}</div><p class="quiet-note">${icon('info')}Manager’s update and recovery controls remain available even when Frameleaf cannot start.</p>`}
function activityPage(){const rows=[...state.activity,{title:'Docker host connected',detail:'Today, 10:24 · Host compatibility checked'},{title:'Immich installation detected',detail:'Today, 10:24 · Configuration read without changes'},{title:'Manager session started',detail:'Today, 10:23 · Local administrator'}];return heading('Activity','Setup, maintenance, and recovery operations on this server.')+(state.operation&&!state.operation.done?`<div class="notice warning mb16">${icon('clock')}<div class="grow"><strong>${operationTitle(state.operation.kind)}</strong><p>${state.operation.paused?'Paused at a saved checkpoint':'Running in the background'}</p></div>${button('View operation','nav:progress','quiet')}</div>`:'')+section('Operation history',rows.map(r=>listRow('check',r.title,r.detail,badge('Complete','good'))).join(''))}
function settingsPage(){return heading('Manager settings','Local administration and recovery for this server.')+section('Access',listRow('user','Local administrator','owner · Independent of Frameleaf photo accounts',button('Preview setup','account','quiet'))+listRow('lock','Local HTTPS','https://home-server:9443 · Local certificate',badge('Enabled','good'))+listRow('shield','Protected session','Secure cookies, CSRF protection and sign-in rate limits',badge('Enabled','good')))+`<div class="mt16">${section('Appearance',`<div class="list-row">${icon('sun')}<div><strong>Theme</strong><p>Uses Frameleaf’s approved light and dark palettes.</p></div><div class="segmented">${['dark','light'].map(t=>`<button data-action="set-theme:${t}" aria-pressed="${state.theme===t}">${t==='dark'?'Dark':'Light'}</button>`).join('')}</div></div>`)}</div><div class="mt16">${section('Recovery & configuration',listRow('document','Configuration export','Export the managed project for manual recovery.',button('Export sample','export-config','quiet'))+listRow('restore','Recover Manager','Replace the Manager container and reconnect its persisted state.',button('View procedure','manual-recovery','quiet'))+listRow('help','Prototype controls','All actions use fictional data in this browser.',button('Reset preview','reset','quiet')))}</div>`}
function maintenanceInspector(){return `<section class="inspector-section"><h2>Home library</h2><dl class="definition"><div><dt>Frameleaf</dt><dd>${state.release}</dd></div><div><dt>Status</dt><dd class="${state.running?'green':'amber'}">${state.running?'Ready':'Stopped'}</dd></div><div><dt>Managed project</dt><dd>frameleaf-home-7f2a</dd></div><div><dt>Owner</dt><dd>Manager</dd></div></dl></section><section class="inspector-section"><h3>Database recovery</h3><p class="mt8">Your latest backup contains the database only. Media must already be available to restore file access.</p><ul class="checklist"><li>${icon('check')}Database only</li><li>${icon('check')}Database dump integrity verified</li><li>${icon('check')}Existing media reused</li></ul></section><section class="inspector-section"><h3>Manager is independent</h3><p class="mt8">Your photo library keeps running if Manager is stopped. Maintenance and recovery stay available when the photo application is offline.</p></section><div class="inspector-footer">Prototype · Sample service and backup status.</div>`}
function render(){const views={welcome,import:importFlow,fresh:freshFlow,restore:restoreFlow,progress:progressView,success:successView,overview,services:servicePage,storage:storagePage,backups:backupPage,updates:updatesPage,activity:activityPage,settings:settingsPage,...onboarding.views};const fn=views[state.view]||welcome;app.innerHTML=shell(fn(),state.view==='import'?importInspector():state.installed?maintenanceInspector():hostInspector());const select=$('#preview-state');select.value=['profile','verify-account','downloads','phone','setup-complete'].includes(state.view)?'mobile':state.scenario==='normal'?(state.installed?'installed':'first'):state.scenario;document.title=`Frameleaf Manager · ${{welcome:'Setup',import:'Immich import',fresh:'New installation',restore:'Restore',overview:'Overview'}[state.view]||'Prototype'}`}
function resetPreview(){clearTimeout(operationTimer);onboarding.reset();Object.assign(state,{view:'welcome',menu:false,flow:'import',step:0,source:'family',scenario:'normal',installed:false,running:true,ml:false,release:'3.2.0',operation:null,backupCount:3,recoveryDownloaded:false,settingsAccepted:false,confirmCutover:false,sourceStopped:false,snapshot:'latest',validation:'ok',activity:[],installOrigin:undefined});setBackupPreview('recent');$('#dialog').close();render()}
function loadInstalled(){clearTimeout(operationTimer);onboarding.reset();state.operation=null;state.scenario='normal';state.installed=true;state.running=true;state.ml=false;state.sourceStopped=true;state.source='family';state.installOrigin='import';go('overview')}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function setTheme(theme){state.theme=theme;document.documentElement.dataset.theme=theme;try{localStorage.setItem('frameleaf-manager-theme',theme)}catch{}render()}
function accountModal(){modal('Secure your Manager','<p>Create an administrator account for Manager. The photo application has its own accounts. Use sample credentials in this prototype.</p><form id="account-form" class="stack">'+field('Administrator name','demo-admin','owner','','text','autocomplete="off" required')+field('Password','demo-password','sample-only-password','At least 12 characters. This sample is never sent or saved.','password','autocomplete="new-password" minlength="12" required')+'</form>',button('Cancel','close-modal','quiet')+button('Save sample account','save-account','primary'))}
function rollbackModal(){modal('Returning to Immich','<p>Your original Immich database is retained. Frameleaf has already written to the shared media locations, so restarting Immich is a separate recovery action.</p>'+notice('Database recovery does not restore media','A database dump cannot undo renamed, deleted or changed files. Verify that the original database or selected backup matches the media before starting Immich.','warning','warning')+'<p>Keep both applications stopped during recovery. Manager does not offer automatic media restoration or promise a complete rollback from this database backup.</p>',button('Done','close-modal','primary'))}
function guide(){modal('Explore Frameleaf Manager','<p>This is an interactive design prototype based on PR #140’s Frameleaf interface. It uses sample data only; no containers, databases, or files are accessed.</p><div class="stack">'+notice('Import Immich','Review the detected source, preserved mappings, settings, existing database backup and controlled cutover.','good','import')+notice('Try mobile onboarding','Choose Mobile onboarding in the Preview menu to jump to user details, optional account creation, app QR codes and shared phone/server readiness.','','user')+notice('Try the other paths','Set up a fresh library, recover a backup, or use the Preview menu to explore an installed server.','','grid')+notice('Explore recovery states','Try recent, old, missing and unusable database backup states, or pause a simulated operation.','','restore')+'</div><p>Version qualification, release signatures, authentication, encryption and recovery results are illustrative. They require implementation and validation before a real installation.</p>',button('Start exploring','close-modal','primary'))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;handle(b.dataset.action,b)});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='backup-preview'){setBackupPreview(el.value);state.step=0;state.confirmCutover=false;render();return;}if(el.id==='preview-state'){resetPreview();if(el.value==='installed')loadInstalled();else if(el.value==='mobile')onboarding.preview();else if(el.value==='multiple'||el.value==='unsupported'){state.scenario=el.value;state.source=el.value==='multiple'?null:'family';state.step=0;go('import')}return}if(el.name==='source'){state.source=el.value;render()}if(el.name==='snapshot'){state.snapshot=el.value}if(el.dataset.check){state[el.dataset.check]=el.checked;const pos=$('.page-scroll').scrollTop;render();$('.page-scroll').scrollTop=pos}if(el.dataset.toggle){state[el.dataset.toggle]=el.checked}if(el.id==='validation-scenario'){state.validation=el.value;render()}});
document.addEventListener('input',e=>{const key=e.target.dataset.field;if(key&&Object.hasOwn(state.fresh,key))state.fresh[key]=e.target.value});
function handle(action){
  if(onboarding.handle(action))return;
  if(action==='theme'){setTheme(state.theme==='dark'?'light':'dark');return}
  if(action.startsWith('set-theme:')){setTheme(action.split(':')[1]);return}
  if(action==='menu'){state.menu=!state.menu;render();return}
  if(action==='close-modal'){$('#dialog').close();return}
  if(action==='start-import'){state.flow='import';state.step=0;state.settingsAccepted=false;state.confirmCutover=false;go('import');return}
  if(action==='import-next'){if((state.step===0&&(state.scenario==='unsupported'||!state.source))||(state.step===1&&!state.settingsAccepted))return;const ids=importStepIds();state.step=ids[Math.min(ids.indexOf(state.step)+1,ids.length-1)];go('import');return}
  if(action==='import-back'){const ids=importStepIds();state.step=ids[Math.max(ids.indexOf(state.step)-1,0)];go('import');return}
  if(action==='start-fresh'){state.flow='install';state.step=0;go('fresh');return}
  if(action==='fresh-next'){const form=$('#admin-form')||$('#storage-form');if(form&&!form.reportValidity())return;if(state.step===1&&['path','database','backup'].some(k=>!state.fresh[k].startsWith('/'))){toast('Enter an absolute server path beginning with /.');return}if(state.step===2&&state.validation&&state.validation!=='ok')return;state.step=Math.min(state.step+1,3);go('fresh');return}
  if(action==='fresh-back'){state.step=Math.max(state.step-1,0);go('fresh');return}
  if(action==='start-restore'||action==='restore-previous'){state.flow='restore';state.step=0;state.snapshot=action==='restore-previous'?'before-update':'latest';go('restore');return}
  if(action==='restore-next'){if(state.step===0&&!$('#restore-key').value){toast('Enter the sample recovery key to continue.');return}state.step=Math.min(state.step+1,2);go('restore');return}
  if(action==='restore-back'){state.step=Math.max(state.step-1,0);go('restore');return}
  if(action==='download-key'){download('frameleaf-DEMO-recovery-key.txt','FRAMELEAF MANAGER — PROTOTYPE ONLY\n\nThis is not a real recovery key.\nSample repository: /srv/backups/frameleaf\nSample key: demo-only-not-valid\n\nIn the real product, store your actual recovery key separately from the server.\n');state.recoveryDownloaded=true;if(state.view==='import')render();toast('Sample recovery key downloaded.');return}
  if(action.startsWith('begin-')){const kind=action.slice(6);if(!Object.hasOwn(stages,kind))return;if(kind==='import'&&!state.confirmCutover)return;if(kind==='import'&&importBackupPlan().skipBackup&&!importBackupPlan(Date.now()).skipBackup){state.backupCheckedAt=Date.now();state.step=2;state.confirmCutover=false;go('import');toast('The previous backup no longer qualifies. Review a new database backup.');return;}$('#dialog').close();startOperation(kind);return}
  if(action==='pause-operation'){state.operation.paused=true;clearTimeout(operationTimer);render();toast('Interruption simulated. Completed steps are retained for this preview session.');return}
  if(action==='resume-operation'){state.operation.paused=false;render();scheduleStage();return}
  if(action==='finish-operation'){if(state.operation?.kind==='import')state.sourceStopped=true;completeOperation();return}
  if(action==='load-installed'){loadInstalled();return}
  if(action==='account'){accountModal();return}
  if(action==='save-account'){if(!$('#account-form').reportValidity())return;$('#dialog').close();toast('Sample administrator setup complete. No credentials were saved.');return}
  if(action==='guide'){guide();return}
  if(action==='reset'){resetPreview();toast('Prototype reset to the first launch.');return}
  if(action==='open-frameleaf'&&state.setup&&!state.setup.managerFinished){go(state.setup.mobile.linked?'phone':'profile');return}
  if(action==='open-frameleaf'){modal('Continue in Frameleaf','<p>Manager will hand you into Frameleaf’s existing onboarding when the application is ready.</p>'+notice(state.installOrigin==='install'?'Create your photo account':'Sign in to your library',state.installOrigin==='install'?'Create the first Frameleaf photo account and start adding your media.':'Use your imported account. Users, albums, and permissions come from the source database.','good','image')+'<p class="mono">https://home-server:2283</p><p>This handoff is simulated. The prototype does not connect to a photo server.</p>',button('Return to Manager','close-modal','primary'));return}
  if(action==='stop-stack'){modal('Stop your photo library','<p>Photo access and background processing will pause. Manager stays available so you can restart or restore your installation.</p>',button('Cancel','close-modal','quiet')+button('Stop services','confirm-stop','danger'));return}
  if(action==='confirm-stop'){state.running=false;$('#dialog').close();state.activity.unshift({title:'Frameleaf services stopped',detail:'Just now · Manual action'});render();toast('Sample services stopped.');return}
  if(action==='start-stack'||action==='restart-stack'){state.running=true;state.activity.unshift({title:action==='start-stack'?'Frameleaf services started':'Frameleaf services restarted',detail:'Just now · Manual action'});render();toast(action==='start-stack'?'Sample services started.':'Sample services restarted and ready.');return}
  if(action==='review-update'){modal('Update to Frameleaf 3.2.1','<p>Manager will verify eligibility, download all compatible images, and create a database recovery point before updating.</p>'+notice('Recovery comes first','If an update cannot be rolled back with images alone, database recovery needs compatible existing media. File changes are not covered by the database backup.','good','restore')+'<p>Expected downtime: 5–10 minutes. The accelerated preview takes a few seconds.</p>',button('Cancel','close-modal','quiet')+button('Update preview','begin-update','primary'));return}
  if(action==='check-updates'){toast('Preview check complete. No newer sample release is available.');return}
  if(action==='rollback'){rollbackModal();return}
  if(action==='export-config'){modal('Export configuration','<p>A real configuration export contains deployment settings and required secrets. Keep it private and store it safely.</p>'+notice('Sample export only','This prototype exports a labeled sample manifest with no passwords, tokens, or real server information.','','document'),button('Cancel','close-modal','quiet')+button('Download sample','download-config','primary'));return}
  if(action==='download-config'){download('frameleaf-manager-DEMO-config.json',JSON.stringify({prototype:true,warning:'Sample only. Not a deployable configuration or recovery archive.',project:'frameleaf-home-7f2a',release:state.release,media:[{source:src().base+'/library',target:'/data',access:'rw'},{source:src().volume,target:'/data/thumbs',access:'rw'},{source:'/srv/family-archive',target:'/external/archive',access:'ro'},{source:'/srv/scans',target:'/photos/scans',access:'ro'}],secrets:'NOT INCLUDED IN PROTOTYPE'},null,2),'application/json');$('#dialog').close();toast('Sample configuration exported.');return}
  if(action==='export-logs'){download('frameleaf-manager-DEMO-logs.txt','PROTOTYPE — SAMPLE LOGS ONLY\nApplication ready\nDatabase connected\nExternal libraries accessible: 2\nCredentials: [REDACTED]\n');toast('Sanitized sample logs downloaded.');return}
  if(action==='manual-recovery'){modal('Recover Manager','<p>Manager’s state is stored separately from the photo database. Replacing Manager should reconnect that state and resume the recorded operation.</p><ol class="timeline">'+[['Keep the existing state volume','Preserve the Manager configuration, journal and recovery keys.'],['Replace only the Manager container','Use a verified Manager image and reconnect the same state and Docker socket.'],['Sign in and review recovery','Manager checks saved operation checkpoints before resuming.'],['Use the protected configuration export if needed','Recover the photo stack manually when Manager state is unavailable.']].map((s,i)=>`<li><span class="stage-icon">${i+1}</span><div><strong>${s[0]}</strong><p>${s[1]}</p></div></li>`).join('')+'</ol><p>This is the proposed recovery experience, not a validated operational procedure.</p>',button('Done','close-modal','primary'));return}
  if(action.startsWith('nav:')){const view=action.split(':')[1];if(view==='progress'&&!state.operation)return;go(view);return}
}
// Page tools expose only prototype navigation and state; operations remain explicit UI actions.
const mcp=document.modelContext;
if(mcp?.registerTool){const lifecycle=new AbortController();const tool={name:'open_manager_preview',title:'Open Manager preview',description:'Open a sample Frameleaf Manager screen. This changes only the visible prototype; it never accesses Docker or media.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['setup','immich-import','new-installation','restore','installed-overview']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='screen')||!['setup','immich-import','new-installation','restore','installed-overview'].includes(input.screen))throw new Error('Choose a valid prototype screen.');if(input.screen==='installed-overview')loadInstalled();else if(input.screen==='setup')handle('nav:welcome');else handle({'immich-import':'start-import','new-installation':'start-fresh',restore:'start-restore'}[input.screen]);return{prototype:true,screen:state.view,step:state.step}}};try{Promise.resolve(mcp.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
const onboarding=createOnboardingUI({state,go,render,icon,esc,button,badge,heading,section,listRow,notice,steps,modal,toast});
setBackupPreview('recent');
if(new URLSearchParams(location.search).get('preview')==='mobile')onboarding.preview();else render();
